const STROKE_ACTIVE = '#1A74E4';
const STROKE_DEFAULT = '#98B0BF';
const getOrientationState = (value, activeValue) => {
	const isActive = value === activeValue;

	return {
		isActive,
		stroke: isActive ? STROKE_ACTIVE : STROKE_DEFAULT,
	};
};

